import numpy as np

W1 = W['W1']

def wnorm(r, c, ch):
    return np.linalg.norm(W1[(r * 10 + c) * 5 + ch, :])

interior = [(r, c) for r in range(1, 9) for c in range(1, 9)]
top_obs = sorted(interior, key=lambda rc: wnorm(rc[0], rc[1], 3), reverse=True)[:8]
top_rew = sorted(interior, key=lambda rc: wnorm(rc[0], rc[1], 2), reverse=True)[:8]

dirs = {'up': (-1, 0, 1), 'down': (1, 0, 2), 'left': (0, -1, 3), 'right': (0, 1, 4)}

def make_X(agent, feature=None, ch=None):
    x = np.zeros(500)
    # border walls
    for i in range(10):
        for r, c in [(0, i), (9, i), (i, 0), (i, 9)]:
            x[(r * 10 + c) * 5 + 3] = 1
    r, c = agent
    x[(r * 10 + c) * 5 + 0] = 1       # agent
    x[(r * 10 + c) * 5 + 4] = 1       # prev = agent
    if feature is not None:
        fr, fc = feature
        x[(fr * 10 + fc) * 5 + ch] = 1
    return x

configs = []
meta = []
for name, top, ch in [('obs', top_obs, 3), ('rew', top_rew, 2)]:
    for T in top:
        for dname, (dr, dc, aidx) in dirs.items():
            ar, ac = T[0] - dr, T[1] - dc
            if 1 <= ar <= 8 and 1 <= ac <= 8:
                configs.append(make_X((ar, ac), None, None))
                meta.append((name, T, dname, aidx, 'base'))
                configs.append(make_X((ar, ac), T, ch))
                meta.append((name, T, dname, aidx, 'feat'))

X = np.array(configs)
logits = forward(X)

def softmax(z):
    z = z - np.max(z, axis=1, keepdims=True)
    e = np.exp(z)
    return e / np.sum(e, axis=1, keepdims=True)

probs = softmax(logits)

deltas = {'obs': [], 'rew': []}
changes = {'obs': 0, 'rew': 0}
total = {'obs': 0, 'rew': 0}
examples = []

for i in range(0, len(meta), 2):
    name, T, dname, aidx, _ = meta[i]
    p_base = probs[i, aidx]
    p_feat = probs[i + 1, aidx]
    deltas[name].append(p_feat - p_base)
    total[name] += 1
    if np.argmax(probs[i]) != np.argmax(probs[i + 1]):
        changes[name] += 1
    if len(examples) < 6:
        examples.append((name, T, dname, round(float(p_base), 3), round(float(p_feat), 3),
                         int(np.argmax(probs[i])), int(np.argmax(probs[i + 1]))))

print("Top obstacle cells (ch3 norm):", [(rc, round(float(wnorm(rc[0], rc[1], 3)), 2)) for rc in top_obs])
print("Top reward cells (ch2 norm):", [(rc, round(float(wnorm(rc[0], rc[1], 2)), 2)) for rc in top_rew])
for name in ['obs', 'rew']:
    arr = np.array(deltas[name])
    print(f"{name}: n={total[name]} mean_delta_prob_toward={arr.mean():+.4f} frac_decrease={np.mean(arr < 0):.2f} action_changed={changes[name]}/{total[name]}")
print("Examples (name, target, dir, p_base, p_feat, argmax_base, argmax_feat):")
for e in examples:
    print(e)

import numpy as np

def make_input(agent, prev=None, moving=None, reward=None, obstacle=None):
    grid = np.zeros((10,10,5), dtype=float)
    # border walls in channel 3
    grid[0,:,3] = 1
    grid[9,:,3] = 1
    grid[:,0,3] = 1
    grid[:,9,3] = 1
    if agent is not None:
        r,c = agent
        grid[r,c,0] = 1
    if moving is not None:
        for r,c in moving:
            grid[r,c,1] = 1
    if reward is not None:
        for r,c in reward:
            grid[r,c,2] = 1
    if obstacle is not None:
        for r,c in obstacle:
            grid[r,c,3] = 1
    if prev is not None:
        for r,c in prev:
            grid[r,c,4] = 1
    return grid.flatten()

scenarios = []
def add(name, **kwargs):
    scenarios.append((name, make_input(**kwargs)))

add("baseline (no prev)", agent=(4,4))
add("prev left (moved right)", agent=(4,4), prev=[(4,3)])
add("prev right (moved left)", agent=(4,4), prev=[(4,5)])
add("prev up (moved down)", agent=(4,4), prev=[(3,4)])
add("prev down (moved up)", agent=(4,4), prev=[(5,4)])
add("prev same", agent=(4,4), prev=[(4,4)])
add("prev left + moving below", agent=(4,4), prev=[(4,3)], moving=[(5,4)])
add("prev left + reward right", agent=(4,4), prev=[(4,3)], reward=[(4,5)])

X = np.array([s[1] for s in scenarios])
logits = forward(X)
probs = np.exp(logits - logits.max(axis=1, keepdims=True))
probs = probs / probs.sum(axis=1, keepdims=True)
actions = np.argmax(logits, axis=1)
action_names = ['no-op','up','down','left','right']

for (name, _), a, p in zip(scenarios, actions, probs):
    print(f"{name:30s} -> {action_names[a]:5s}  sm={np.round(p,3)}")
